import java.lang.reflect.Field;

public class Repro2 {
  public static void main(String[] args) throws Exception {
    int base = Integer.MAX_VALUE;
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    Polygon poly = new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon});
    Component2D tree = Polygon2D.create(poly);
    GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(tree);
    int docLat = GeoEncodingUtils.encodeLatitude(GeoEncodingUtils.decodeLatitude(base - 2));
    int docLon = GeoEncodingUtils.encodeLongitude(GeoEncodingUtils.decodeLongitude(base - 2));

    Class<?> c = pred.getClass();
    while (c != null && c != Object.class) {
      for (Field f : c.getDeclaredFields()) {
        f.setAccessible(true);
        Object v = f.get(pred);
        if (v instanceof byte[] bytes) {
          StringBuilder sb = new StringBuilder();
          for (byte b : bytes) sb.append(b).append(" ");
          System.out.println(f.getName() + " = [" + sb.toString().trim() + "]");
        } else {
          System.out.println(f.getName() + " = " + v);
        }
      }
      c = c.getSuperclass();
    }
    System.out.println("test -> " + pred.test(docLat, docLon));
  }
}
