package org.apache.lucene.geo;

import java.util.Random;

public class Fuzz {
  public static void main(String[] args) {
    Random r = new Random(42);
    int checked = 0, mismatches = 0;
    for (int iter = 0; iter < 20000; iter++) {
      boolean nearPole = r.nextInt(3) == 0;
      double minLat = nearPole ? 89.999 : -90 + 180 * r.nextDouble();
      double maxLat = nearPole ? 90.0 : minLat + 10 * r.nextDouble();
      if (maxLat > 90) maxLat = 90;
      double minLon = -180 + 360 * r.nextDouble();
      double maxLon = minLon + 5 * r.nextDouble();
      if (maxLon > 180) maxLon = 180;
      if (minLat >= maxLat || minLon >= maxLon) continue;
      Polygon poly;
      try {
        poly = new Polygon(
            new double[] {minLat, minLat, maxLat, maxLat, minLat},
            new double[] {minLon, maxLon, maxLon, minLon, minLon});
      } catch (Exception e) { continue; }
      Component2D tree = Polygon2D.create(poly);
      GeoEncodingUtils.Component2DPredicate pred;
      try {
        pred = GeoEncodingUtils.createComponentPredicate(tree);
      } catch (Exception e) { continue; }
      // test points: random within bbox + corners encoded
      for (int p = 0; p < 50; p++) {
        double plat, plon;
        if (r.nextBoolean()) {
          plat = minLat + (maxLat - minLat) * r.nextDouble();
          plon = minLon + (maxLon - minLon) * r.nextDouble();
        } else {
          int eLat = r.nextInt() ;
          int eLon = r.nextInt();
          plat = GeoEncodingUtils.decodeLatitude(eLat);
          plon = GeoEncodingUtils.decodeLongitude(eLon);
        }
        int encLat, encLon;
        try {
          encLat = GeoEncodingUtils.encodeLatitude(plat);
          encLon = GeoEncodingUtils.encodeLongitude(plon);
        } catch (Exception e) { continue; }
        boolean direct;
        try { direct = tree.contains(plon, plat); } catch (Exception e) { continue; }
        boolean predResult = pred.test(encLat, encLon);
        checked++;
        // predicate must never contradict direct containment for the decoded point
        if (predResult != direct) {
          // allowed disagreement only if point encodes outside the grid cell relation boundaries;
          // count as mismatch for review
          mismatches++;
          if (mismatches < 5) {
            System.out.println("MISMATCH iter=" + iter + " lat=" + plat + " lon=" + plon
                + " pred=" + predResult + " direct=" + direct);
          }
        }
      }
    }
    System.out.println("checked=" + checked + " mismatches=" + mismatches);
  }
}
