package org.apache.lucene.geo;

import org.apache.lucene.util.SloppyMath;

public class FullTest {
  static int failures = 0;

  static void check(String name, boolean ok) {
    System.out.println((ok ? "PASS " : "FAIL ") + name);
    if (!ok) failures++;
  }

  public static void main(String[] args) {
    int base = Integer.MAX_VALUE;

    // --- doc values path: predicate.test on encoded doc point (both subclasses reduce to this) ---
    {
      double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
      double maxLat = GeoEncodingUtils.decodeLatitude(base);
      double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
      double maxLon = GeoEncodingUtils.decodeLongitude(base);
      Polygon poly = new Polygon(
          new double[] {minLat, minLat, maxLat, maxLat, minLat},
          new double[] {minLon, maxLon, maxLon, minLon, minLon});
      Component2D tree = Polygon2D.create(poly);
      GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(tree);
      int docLat = GeoEncodingUtils.encodeLatitude(GeoEncodingUtils.decodeLatitude(base - 2));
      int docLon = GeoEncodingUtils.encodeLongitude(GeoEncodingUtils.decodeLongitude(base - 2));
      check("northPole docvalues predicate.test", pred.test(docLat, docLon));
    }

    // --- south pole mirror ---
    {
      int b = Integer.MIN_VALUE;
      double minLat = GeoEncodingUtils.decodeLatitude(b + 3);
      double maxLat = GeoEncodingUtils.decodeLatitude(b);
      double minLon = GeoEncodingUtils.decodeLongitude(b + 3);
      double maxLon = GeoEncodingUtils.decodeLongitude(b);
      Polygon poly = new Polygon(
          new double[] {minLat, minLat, maxLat, maxLat, minLat},
          new double[] {minLon, maxLon, maxLon, minLon, minLon});
      Component2D tree = Polygon2D.create(poly);
      GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(tree);
      int docLat = GeoEncodingUtils.encodeLatitude(GeoEncodingUtils.decodeLatitude(b + 2));
      int docLon = GeoEncodingUtils.encodeLongitude(GeoEncodingUtils.decodeLongitude(b + 2));
      check("southPole docvalues predicate.test", pred.test(docLat, docLon));
    }

    // --- point-index path: whole-cell relate + predicate for leaf of single point ---
    {
      double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
      double maxLat = GeoEncodingUtils.decodeLatitude(base);
      double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
      double maxLon = GeoEncodingUtils.decodeLongitude(base);
      Polygon poly = new Polygon(
          new double[] {minLat, minLat, maxLat, maxLat, minLat},
          new double[] {minLon, maxLon, maxLon, minLon, minLon});
      Component2D tree = Polygon2D.create(poly);
      int docLat = GeoEncodingUtils.encodeLatitude(GeoEncodingUtils.decodeLatitude(base - 2));
      int docLon = GeoEncodingUtils.encodeLongitude(GeoEncodingUtils.decodeLongitude(base - 2));
      Relation rel = tree.relate(
          GeoEncodingUtils.decodeLongitude(docLon), GeoEncodingUtils.decodeLongitude(docLon),
          GeoEncodingUtils.decodeLatitude(docLat), GeoEncodingUtils.decodeLatitude(docLat));
      check("northPole point-index cell relate INSIDE", rel == Relation.CELL_INSIDE_QUERY);
    }

    // --- DistancePredicate near poles (upstream fix touched it too) ---
    {
      // point near north pole, radius covering a narrow band
      double lat = GeoEncodingUtils.decodeLatitude(base - 2);
      double lon = GeoEncodingUtils.decodeLongitude(base - 2);
      double radius = 1200; // meters
      GeoEncodingUtils.DistancePredicate dp =
          GeoEncodingUtils.createDistancePredicate(lat, lon, radius);
      // doc at same location
      int encLat = GeoEncodingUtils.encodeLatitude(lat);
      int encLon = GeoEncodingUtils.encodeLongitude(lon);
      check("northPole distance predicate self", dp.test(encLat, encLon));
      // point slightly farther than radius must be rejected
      double lat2 = GeoEncodingUtils.decodeLatitude(base - 5000);
      double dist = SloppyMath.haversinMeters(lat, lon, lat2, lon);
      GeoEncodingUtils.DistancePredicate dp2 =
          GeoEncodingUtils.createDistancePredicate(lat, lon, dist * 0.5);
      check("northPole distance predicate far point rejected",
          dp2.test(GeoEncodingUtils.encodeLatitude(lat2), encLon) == false);

      // near south pole
      double slat = GeoEncodingUtils.decodeLatitude(Integer.MIN_VALUE + 2);
      GeoEncodingUtils.DistancePredicate dp3 =
          GeoEncodingUtils.createDistancePredicate(slat, lon, radius);
      check("southPole distance predicate self",
          dp3.test(GeoEncodingUtils.encodeLatitude(slat), encLon));
    }

    // --- dateline-crossing sanity (lon wrap path unchanged) ---
    {
      double minLat = -10, maxLat = 10;
      Polygon poly = new Polygon(
          new double[] {minLat, minLat, maxLat, maxLat, minLat},
          new double[] {179.9999, -179.9999, -179.9999, 179.9999, 179.9999});
      Component2D tree = Polygon2D.create(poly);
      GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(tree);
      int docLat = GeoEncodingUtils.encodeLatitude(0);
      int docLon = GeoEncodingUtils.encodeLongitude(-179.99995);
      check("dateline crossing predicate.test", pred.test(docLat, docLon));
    }

    if (failures > 0) { System.out.println("FAILURES: " + failures); System.exit(1); }
    System.out.println("ALL PASS");
  }
}
